import json
out={}
for name,n,h,q,k in [('command-a',64,12288,96,8),('r7b',32,4096,32,8),('r7b-arabic',32,4096,32,8)]:
 s=[4096 if (i+1)%4 != 0 else -1 for i in range(n)]
 out[name]={'head_dim_derived':h//q,'q_width':q*128,'kv_width':k*128,'q_heads_per_kv':q//k,'local_layers':sum(x>=0 for x in s),'global_layers_1_based':[i+1 for i,x in enumerate(s) if x<0]}
out['pattern_default_1']=[4096 if (i+1)%1 != 0 else -1 for i in range(4)]
out['logit_default']=0.0625
print(json.dumps(out))

